<?php
declare(strict_types=1);
namespace Plugins\Modules\Phonetics\Http\Controllers;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Str;use Illuminate\View\View;use Plugins\Modules\Phonetics\Models\PhoneticSetting;use Plugins\Modules\Phonetics\Models\PhoneticEntry;
final class PhoneticsAdminController extends Controller{public function index():View{return view('phonetics::admin.index',['setting'=>PhoneticSetting::current(),'entries'=>PhoneticEntry::query()->orderBy('sort_order')->paginate(30)]);}public function updateSettings(Request $r){$v=$r->validate(['enabled'=>'nullable|boolean','course_slug'=>'required|string|max:120','course_title'=>'required|string|max:160','require_course_enrollment'=>'nullable|boolean','show_articulatory_notes'=>'nullable|boolean']);$s=PhoneticSetting::query()->firstOrNew(['id'=>1]);$s->fill(['enabled'=>$r->boolean('enabled'),'course_slug'=>Str::slug($v['course_slug']),'course_title'=>$v['course_title'],'require_course_enrollment'=>$r->boolean('require_course_enrollment'),'show_articulatory_notes'=>$r->boolean('show_articulatory_notes')])->save();Cache::forget('phonetics.settings');return back()->with('status','Phonetics settings saved.');}public function store(Request $r){$v=$r->validate(['word'=>'required|string|max:80','category'=>'required|in:rhoticity,trap-bath,t-flapping,lot-vowel,yod-dropping,word-stress','uk_ipa'=>'required|string|max:100','us_ipa'=>'required|string|max:100','uk_note'=>'nullable|string|max:255','us_note'=>'nullable|string|max:255','example_sentence'=>'nullable|string|max:255']);$v['sort_order']=(PhoneticEntry::query()->max('sort_order')??0)+1;$v['is_active']=true;PhoneticEntry::query()->create($v);return back()->with('status','Entry added.');}public function destroy(PhoneticEntry $entry){$entry->delete();return back()->with('status','Entry deleted.');}}